function validate([trees]) {
  if (!Array.isArray(trees) || trees.length < 1 || trees.length > 3000) return 'trees needs 1 to 3000 points.';
  for (const t of trees) {
    if (!Array.isArray(t) || t.length !== 2) return 'Each tree is a pair [x, y].';
    if (t.some(v => !Number.isInteger(v) || v < 0 || v > 3000)) return 'Coordinates are whole numbers from 0 to 3000.';
  }
  return null;
}

