function outerTrees(trees) {
  const points = trees.map(([x, y]) => [x, y]);
  for (let i = points.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [points[i], points[j]] = [points[j], points[i]];
  }

  const inside = (circle, p) => Math.hypot(p[0] - circle[0], p[1] - circle[1]) <= circle[2] + 1e-7;
  const fromTwo = (a, b) => [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, Math.hypot(a[0] - b[0], a[1] - b[1]) / 2];
  const fromThree = (a, b, c) => {
    const bx = b[0] - a[0];
    const by = b[1] - a[1];
    const cx = c[0] - a[0];
    const cy = c[1] - a[1];
    const d = 2 * (bx * cy - by * cx);
    const ux = (cy * (bx * bx + by * by) - by * (cx * cx + cy * cy)) / d;
    const uy = (bx * (cx * cx + cy * cy) - cx * (bx * bx + by * by)) / d;
    return [a[0] + ux, a[1] + uy, Math.hypot(ux, uy)];
  };

  let circle = [points[0][0], points[0][1], 0];
  for (let i = 1; i < points.length; i++) {
    if (inside(circle, points[i])) continue;
    circle = [points[i][0], points[i][1], 0];
    for (let j = 0; j < i; j++) {
      if (inside(circle, points[j])) continue;
      circle = fromTwo(points[i], points[j]);
      for (let k = 0; k < j; k++) {
        if (!inside(circle, points[k])) {
          circle = fromThree(points[i], points[j], points[k]);
        }
      }
    }
  }
  return circle;
}

