function outerTrees(trees) {
  const n = trees.length;
  const covers = (cx, cy, r) => trees.every(([x, y]) => Math.hypot(x - cx, y - cy) <= r + 1e-7);
  let best = null;
  const consider = (cx, cy, r) => {
    if ((best === null || r < best[2]) && covers(cx, cy, r)) best = [cx, cy, r];
  };
  for (const [x, y] of trees) consider(x, y, 0);
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const [ax, ay] = trees[i], [bx, by] = trees[j];
      consider((ax + bx) / 2, (ay + by) / 2, Math.hypot(ax - bx, ay - by) / 2);
      for (let k = j + 1; k < n; k++) {
        const [cx, cy] = trees[k];
        const d = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by));
        if (d === 0) continue;
        const sa = ax * ax + ay * ay, sb = bx * bx + by * by, sc = cx * cx + cy * cy;
        const ox = (sa * (by - cy) + sb * (cy - ay) + sc * (ay - by)) / d;
        const oy = (sa * (cx - bx) + sb * (ax - cx) + sc * (bx - ax)) / d;
        consider(ox, oy, Math.hypot(ax - ox, ay - oy));
      }
    }
  }
  return best;
}

