function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const spans = [3, 10, 3000];
  const span = size === 'large' ? 3000 : spans[Math.floor(rand() * spans.length)];
  const pick = () => Math.floor(rand() * (span + 1));
  const shape = rand();
  const trees = [];
  for (let i = 0; i < n; i++) {
    if (shape < 0.15) trees.push([pick(), 7 % (span + 1)]);
    else if (shape < 0.25) { const t = pick(); trees.push([t, t]); }
    else if (size === 'large' && shape < 0.6) {
      // Points scattered inside a disc, so many lie near the final boundary.
      const angle = rand() * 2 * Math.PI, radius = 1500 * Math.sqrt(rand());
      trees.push([Math.round(1500 + radius * Math.cos(angle)), Math.round(1500 + radius * Math.sin(angle))]);
    } else trees.push([pick(), pick()]);
  }
  return [trees];
}
